using IKP.Application.Auth.Authorization;
using IKP.Domain.Entities.App.HR.DevelopmentAndAttestation.Attestation;
using IKP.Infrastructure.Persistence;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace IKP.Api.Controllers.HR.Attestation;

[ApiController,Route("api/hr/attestations"),Authorize(Policy=AuthorizationPolicyNames.EmployeesRead)]
public sealed class AttestationsController(IDbContextFactory<AppDbContext> factory):ControllerBase{
 public sealed record CreateRequest(Guid EmployeeId,Guid? ManagerEmployeeId,Guid MatrixAssessmentId,string Title,DateOnly? PlannedDate);
 public sealed record SectionRequest(Guid AttestationSectionTypeId,string Title,int SortOrder);
 public sealed record QuestionRequest(Guid QuestionTypeId,int SortOrder,string Text,bool IsAiDraft,bool IsApproved,bool IsOralAnswer,bool IsSelfWriteAnswer,string? AiPromptContext,decimal? MaxScore);
 public sealed record OptionRequest(string Text,bool IsCorrect,int SortOrder);
 [HttpGet("{id:guid}")] public async Task<IActionResult>Get(Guid id,CancellationToken ct){await using var db=await factory.CreateDbContextAsync(ct);var x=await db.Attestations.AsNoTracking().Where(x=>x.Id==id&&!x.IsDeleted).Select(x=>new{x.Id,x.EmployeeId,x.ManagerEmployeeId,x.MatrixAssessmentId,x.Title,x.PlannedDate,x.CompletedDate,x.FinalScore,x.FinalComment,Sections=x.Sections.Where(s=>!s.IsDeleted).OrderBy(s=>s.SortOrder).Select(s=>new{s.Id,s.AttestationSectionTypeId,s.Title,s.SortOrder,Questions=s.Questions.Where(q=>!q.IsDeleted).OrderBy(q=>q.SortOrder).Select(q=>new{q.Id,q.QuestionTypeId,q.SortOrder,q.Text,q.IsAiDraft,q.IsApproved,q.IsOralAnswer,q.IsSelfWriteAnswer,q.AiPromptContext,q.MaxScore,Options=q.Options.Where(o=>!o.IsDeleted).OrderBy(o=>o.SortOrder).Select(o=>new{o.Id,o.Text,o.IsCorrect,o.SortOrder})})})}).SingleOrDefaultAsync(ct);return x is null?NotFound():Ok(x);}
 [HttpPost,Authorize(Policy=AuthorizationPolicyNames.EmployeesManage)] public async Task<IActionResult>Create(CreateRequest r,CancellationToken ct){await using var db=await factory.CreateDbContextAsync(ct);var x=new Domain.Entities.App.HR.DevelopmentAndAttestation.Attestation.Attestation { EmployeeId=r.EmployeeId,ManagerEmployeeId=r.ManagerEmployeeId,MatrixAssessmentId=r.MatrixAssessmentId,Title=r.Title.Trim(),PlannedDate=r.PlannedDate};db.Attestations.Add(x);await db.SaveChangesAsync(ct);return CreatedAtAction(nameof(Get),new{id=x.Id},new{x.Id});}
 [HttpPost("{id:guid}/sections"),Authorize(Policy=AuthorizationPolicyNames.EmployeesManage)] public async Task<IActionResult>AddSection(Guid id,SectionRequest r,CancellationToken ct){await using var db=await factory.CreateDbContextAsync(ct);if(!await db.Attestations.AnyAsync(x=>x.Id==id&&!x.IsDeleted,ct))return NotFound();var x=new AttestationSection{AttestationId=id,AttestationSectionTypeId=r.AttestationSectionTypeId,Title=r.Title.Trim(),SortOrder=r.SortOrder};db.AttestationSections.Add(x);await db.SaveChangesAsync(ct);return Ok(new{x.Id});}
 [HttpPost("sections/{sectionId:guid}/questions"),Authorize(Policy=AuthorizationPolicyNames.EmployeesManage)] public async Task<IActionResult>AddQuestion(Guid sectionId,QuestionRequest r,CancellationToken ct){await using var db=await factory.CreateDbContextAsync(ct);if(!await db.AttestationSections.AnyAsync(x=>x.Id==sectionId&&!x.IsDeleted,ct))return NotFound();var x=new AttestationQuestion{SectionId=sectionId,QuestionTypeId=r.QuestionTypeId,SortOrder=r.SortOrder,Text=r.Text.Trim(),IsAiDraft=r.IsAiDraft,IsApproved=r.IsApproved,IsOralAnswer=r.IsOralAnswer,IsSelfWriteAnswer=r.IsSelfWriteAnswer,AiPromptContext=r.AiPromptContext,MaxScore=r.MaxScore};db.AttestationQuestions.Add(x);await db.SaveChangesAsync(ct);return Ok(new{x.Id});}
 [HttpPost("questions/{questionId:guid}/options"),Authorize(Policy=AuthorizationPolicyNames.EmployeesManage)] public async Task<IActionResult>AddOption(Guid questionId,OptionRequest r,CancellationToken ct){await using var db=await factory.CreateDbContextAsync(ct);if(!await db.AttestationQuestions.AnyAsync(x=>x.Id==questionId&&!x.IsDeleted,ct))return NotFound();var x=new AttestationAnswerOption{QuestionId=questionId,Text=r.Text.Trim(),IsCorrect=r.IsCorrect,SortOrder=r.SortOrder};db.AttestationAnswerOptions.Add(x);await db.SaveChangesAsync(ct);return Ok(new{x.Id});}
 [HttpPost("questions/{questionId:guid}/approve"),Authorize(Policy=AuthorizationPolicyNames.EmployeesManage)] public async Task<IActionResult>ApproveQuestion(Guid questionId,CancellationToken ct){await using var db=await factory.CreateDbContextAsync(ct);var x=await db.AttestationQuestions.SingleOrDefaultAsync(x=>x.Id==questionId&&!x.IsDeleted,ct);if(x is null)return NotFound();x.IsApproved=true;x.IsAiDraft=false;await db.SaveChangesAsync(ct);return NoContent();}
}
